import pathlib
p = pathlib.Path("src/jj/session.rs"); s = p.read_text()
old = """    /// Snapshot, then squash all of `source`'s changes into
    /// `target`, keeping the target's description"""
assert s.count(old) == 1
new = """    /// Snapshot, then restore the repo's local state to the
    /// operation named by `op_str`, leaving what is known of the
    /// remotes as it is now (`jj op restore --what repo <op>`).
    ///
    /// The heads, local bookmarks, local tags, and working-copy
    /// commit become the target's, and the working copy is updated
    /// to match. The remote-tracking refs stay at their current
    /// values, which is the difference from `restore_op`: undoing a
    /// fetch with `restore_op` puts `<b>@<remote>` back while the
    /// git ref it mirrors stays fetched, so a later fetch finds
    /// nothing new to import and the remote's change is never seen
    /// again. Kept current, the refs go on saying what the remote
    /// holds. Their targets are added to the heads, since the
    /// target's heads predate them.
    pub fn restore_local(&mut self, op_str: &str) -> Result<()> {
        self.snapshot()?;
        let target_op = jj_lib::op_walk::resolve_op_for_load(self.workspace.repo_loader(), op_str)
            .block_on()?;
        let mut new_view = target_op.view().block_on()?.store_view().clone();
        let current_view = self.repo.view().store_view();
        new_view.git_refs = current_view.git_refs.clone();
        new_view.git_heads = current_view.git_heads.clone();
        new_view.remote_views = current_view.remote_views.clone();
        for remote_view in new_view.remote_views.values() {
            for remote_ref in remote_view.bookmarks.values() {
                new_view
                    .head_ids
                    .extend(remote_ref.target.added_ids().cloned());
            }
        }
        let mut tx = self.start_tx();
        tx.repo_mut().set_view(new_view);
        self.finish_tx(
            tx,
            &format!("restore local state to operation {}", target_op.id().hex()),
        )
    }

"""
s = s.replace(old, new + old)
p.write_text(s)
EOF

