236	pub fn sync(ctx: &mut Context, params: &SyncParams) -> Result<(), Box<dyn std::error::Error>> {
237	    let repos = resolve_repos(params.repo.as_deref(), params.scope.as_ref())?;
238	    if params.quiet {
239	        let prev = log::max_level();
240	        log::set_max_level(LevelFilter::Warn);
241	        let result = sync_repos(ctx, &repos, params);
242	        log::set_max_level(prev);
243	        result
244	    } else {
245	        sync_repos(ctx, &repos, params)
246	    }
247	}
248	
249	/// Sync the given repos against their remotes.
250	///
251	/// Orchestrates the full flow: pre-flight clean-check on every repo,
252	/// snapshot each repo's current op id in memory, then hand off to
253	/// `run_plan` for fetch + classify + act, then reposition `@`.
254	///
255	/// **Stop-on-error**: a failure leaves every repo exactly where the
256	/// failing step stopped so the user can inspect what happened:
257	/// nothing is auto-reverted. The error report names each repo's
258	/// pre-sync op id with the explicit `jj op restore` undo. The
259	/// snapshots die with the invocation.
260	///
261	/// Paths may be relative (resolved against the process cwd) or
262	/// absolute. Tests use absolute tempdir paths to avoid cwd dependence
263	/// under parallel `cargo test`.
264	pub fn sync_repos(
265	    ctx: &mut Context,
266	    repos: &[PathBuf],
267	    params: &SyncParams,
268	) -> Result<(), Box<dyn std::error::Error>> {
269	    debug!(
270	        "sync: enter (bookmark={}, remote={})",
271	        params.bookmark, params.remote
272	    );
273	
274	    // Preflight: verify bookmark tracking on every repo before any
275	    // fetch/rebase. Implements "Non-tracking-remote bookmark detection",
276	    // design at:
277	    //   https://github.com/winksaville/vc-x1/blob/main/notes/chores/chores-06.md#non-tracking-remote-bookmark-detection-design
278	    for repo in repos {
279	        let bookmark = repo_bookmark(repo, &params.bookmark);
280	        if bookmark != params.bookmark {
281	            info!(
282	                "{}: bot repo, syncing 'main' ('{}' is a work repo bookmark)",
283	                repo.display(),
284	                params.bookmark
285	            );
286	        }
287	        crate::common::verify_tracking(repo, bookmark)?;
288	    }
289	
290	    // In-memory only: the snapshot exists to be printed by this
291	    // invocation's failure report, never persisted for a later one.
292	    let mut snapshots: Vec<(PathBuf, String)> = Vec::new();
293	    for repo in repos {
294	        let op_id = jj::current_op_id(repo)?;
295	        debug!("{}: op snapshot = {op_id}", repo.display());
296	        snapshots.push((repo.clone(), op_id));
297	    }
298	
299	    // Run the plan, then reposition `@` onto the freshly-synced
300	    // bookmark. Both live inside the same stop-on-error region: any
301	    // failure falls through to the report below with state left in
302	    // place.
303	    //
304	    // A look-only run and a repo left diverged skip the reposition:
305	    // neither moved a bookmark, so `@` has nowhere new to go.
306	    let result = run_plan(ctx, &snapshots, params).and_then(|left| {
307	        if !params.dry_run {
308	            for (repo, _) in &snapshots {
309	                if !left.contains(repo) {
310	                    reposition_at(repo, repo_bookmark(repo, &params.bookmark), params)?;
311	                }
312	            }
313	        }
314	        Ok(left)
315	    });
316	
317	    let left = match result {
318	        Ok(left) => left,
319	        Err(e) => {
320	            warn!("sync failed: {e}");
321	            warn!("stopping: state left as-is for inspection (no auto-revert)");
322	            warn!("pre-sync op snapshot per repo:");
323	            for (repo, op_id) in &snapshots {
324	                warn!("  {}: op {op_id}", repo.display());
325	            }
326	            warn!("undo per repo: jj op restore <op> -R <repo>");
327	            debug!("sync: exit");
328	            return Err(e);
329	        }
330	    };
331	
332	    debug!("sync: exit");
333	    // Not a failed step, so no snapshot report: every repo is where
334	    // it should be, and the diverged ones are exactly as found.
335	    if !left.is_empty() {
336	        let names: Vec<String> = left.iter().map(|r| r.display().to_string()).collect();
337	        return Err(format!(
338	            "diverged and left as found: {}: rerun with --rebase to rebase onto the remote",
339	            names.join(", ")
340	        )
341	        .into());
342	    }
343	    Ok(())
344	}
345	
346	/// Clean-case summary tail ("<N> repo(s) ..." prefixed at the emit
347	/// site). Shared with main.rs's `long_about` so the documented
348	/// output shape can't drift from the emitted one.
349	pub const UP_TO_DATE_MSG: &str = "up to date, nothing to sync";
350	
351	/// Fetch and classify each repo, then act, or in a look-only run
352	/// put back what the fetch moved.
353	///
354	/// Returns the repos left diverged, empty when every repo synced
355	/// and always empty for a look-only run. Returns `Err` on the first
356	/// failure so the caller can stop and report. Partial progress
357	/// across repos is left in place for inspection (see `sync_repos`).
358	fn run_plan(
359	    ctx: &mut Context,
360	    snapshots: &[(PathBuf, String)],
361	    params: &SyncParams,
362	) -> Result<Vec<PathBuf>, Box<dyn std::error::Error>> {
363	    // Phase 1: fetch + classify silently.
364	    //
365	    // Each repo's fetch stderr is captured (rather than streamed to
366	    // `info!` via `common::run`) so we can decide after classification
367	    // whether to surface it. `jj git fetch`'s routine "Nothing
368	    // changed." chatter is the main thing we're suppressing here:
369	    // if nothing needs action, the user shouldn't see it.
370	    let mut fetched: Vec<(PathBuf, Vec<String>)> = Vec::new();
371	    let mut ctxs: Vec<RepoCtx> = Vec::new();
372	    //
373	    // The bookmark is read before the fetch: the fetch moves a
374	    // tracked bookmark that is behind and conflicts one that
375	    // diverged, so afterwards neither state can be told from the
376	    // bookmark alone.
377	    for (repo, op_id) in snapshots {
378	        let bookmark = repo_bookmark(repo, &params.bookmark);
379	        let found = local_bookmark_heads(repo, bookmark)?;
380	        let lines = fetch_silent(ctx, repo, &params.remote)?;
381	        fetched.push((repo.clone(), lines));
382	        let state = classify(repo, &found, bookmark, &params.remote)?;
383	        ctxs.push(RepoCtx {
384	            path: repo.clone(),
385	            op_id: op_id.clone(),
386	            found,
387	            state,
388	        });
389	    }
390	
391	    // Ahead is not level either, and a reader of the report wants to
392	    // hear of an unpushed bookmark, so only up-to-date is quiet.
393	    let any_action_needed = ctxs
394	        .iter()
395	        .any(|c| !matches!(c.state, State::UpToDate | State::NoRemote));
396	
397	    // Phase 2: emit status. `--quiet` is enforced globally via the
398	    // log-level clamp in `sync()`, so these `info!` calls are already
399	    // suppressed in scripts. We just shape the output here.
400	    if !any_action_needed {
401	        let n = ctxs.len();
402	        let noun = if n == 1 { "repo is" } else { "repos are" };
403	        info!("sync: {n} {noun} {UP_TO_DATE_MSG}");
404	    } else {
405	        for (repo, lines) in &fetched {
406	            info!("{}: fetch {}", repo.display(), params.remote);
407	            for line in lines {
408	                info!("{line}");
409	            }
410	        }
411	        for ctx in &ctxs {
412	            log_state(&ctx.path, &ctx.state, params.dry_run);
413	        }
414	    }
415	
416	    // Phase 3: act, or for a look put the bookmark back. Repositioning
417	    // `@` onto the synced bookmark happens after `run_plan` returns
418	    // (see `sync_repos`), outside the revert region.
419	    let mut left = Vec::new();
420	    for repo_ctx in &ctxs {
421	        if params.dry_run {
422	            put_back(ctx, repo_ctx, params)?;
423	        } else if act_on_state(ctx, repo_ctx, params)? == Acted::LeftDiverged {
424	            left.push(repo_ctx.path.clone());
425	        }
426	    }
427	
428	    Ok(left)
429	}
430	
431	/// Put `repo_ctx`'s bookmark back where it was before the fetch, when
432	/// the fetch moved or conflicted it.
433	///
434	/// A bookmark that was already conflicted before the fetch has no one
435	/// commit to go back to and is left as the fetch left it.
436	fn put_back(
437	    ctx: &mut Context,
438	    repo_ctx: &RepoCtx,
439	    params: &SyncParams,
