cut("/// Per-repo context accumulated between the snapshot and action phases.",
    "/// CLI entry point for the `sync` subcommand.", """/// Per-repo context accumulated between the snapshot and action phases.
///
/// - `found`: the commit ids the bookmark pointed at before the
///   fetch, one normally and several when it was already conflicted.
///   The state is classified from it.
/// - `conflicted`: the fetch left a conflict the repo did not have,
///   the remote having rewritten a commit under local work.
#[derive(Debug)]
struct RepoCtx {
    path: PathBuf,
    found: Vec<String>,
    state: State,
    conflicted: bool,
}

/// What acting on one repo's state came to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Acted {
    /// Nothing to do, or the bookmark was converged.
    Synced,
    /// Diverged with no go to rebase: the repo is to be restored.
    NoGo,
}

/// One repo as sync found it, and a watch for writes that are not
/// sync's own.
///
/// - `found_op`: the op id after the opening snapshot, the state a
///   restore returns to.
/// - `last_op`: the op id after sync's latest verb. Every verb
///   snapshots first, so an operation that appears between two of
///   them was made by someone else: a live session writing the
///   working copy, or another command.
/// - `foreign`: such an operation was seen. A restore would rewind
///   it, so none is made.
#[derive(Debug)]
struct Watch {
    path: PathBuf,
    found_op: String,
    last_op: String,
    foreign: bool,
}

impl Watch {
    /// Snapshot `repo` and start watching it from there.
    fn open(ctx: &mut Context, repo: &Path) -> Result<Self, Box<dyn std::error::Error>> {
        ctx.session(repo)?.snapshot()?;
        let op = jj::current_op_id(repo)?;
        debug!("{}: op snapshot = {op}", repo.display());
        Ok(Self {
            path: repo.to_path_buf(),
            found_op: op.clone(),
            last_op: op,
            foreign: false,
        })
    }

    /// Call before a verb: snapshot, and note a write that was not
    /// sync's own.
    fn look(&mut self, ctx: &mut Context) -> Result<(), Box<dyn std::error::Error>> {
        ctx.session(&self.path)?.snapshot()?;
        let op = jj::current_op_id(&self.path)?;
        if op != self.last_op {
            debug!("{}: foreign operation {op}", self.path.display());
            self.foreign = true;
            self.last_op = op;
        }
        Ok(())
    }

    /// Call after a verb: its operations are sync's own.
    fn mine(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        self.last_op = jj::current_op_id(&self.path)?;
        Ok(())
    }

    /// Put the repo back as found. Returns false, having said why
    /// and how to undo by hand, when a foreign write forbids it.
    fn restore(&mut self, ctx: &mut Context) -> Result<bool, Box<dyn std::error::Error>> {
        self.look(ctx)?;
        if self.last_op == self.found_op {
            return Ok(true);
        }
        let r = self.path.display();
        if self.foreign {
            warn!("{r}: the working copy changed while sync ran, so it is not restored");
            warn!("{r}: undo by hand: jj op restore {} -R {r}", self.found_op);
            return Ok(false);
        }
        ctx.session(&self.path)?.restore_local(&self.found_op)?;
        self.mine()?;
        info!("{r}: restored as found");
        Ok(true)
    }
}

""")

