cut("/// Sync the given repos against their remotes.\n",
    "/// Clean-case summary tail", """/// Sync the given repos against their remotes.
///
/// Orchestrates the full flow: tracking preflight on every repo, a
/// `Watch` opened on each, then `run_plan` for fetch + classify +
/// act, then reposition `@`.
///
/// **All or nothing**: a failure restores every repo as found (see
/// `Watch::restore`), and with `--keep` leaves every repo where the
/// failing step stopped, the report naming each repo's pre-sync op
/// id with the explicit `jj op restore` undo. The watches die with
/// the invocation.
///
/// Paths may be relative (resolved against the process cwd) or
/// absolute. Tests use absolute tempdir paths to avoid cwd dependence
/// under parallel `cargo test`.
pub fn sync_repos(
    ctx: &mut Context,
    repos: &[PathBuf],
    params: &SyncParams,
) -> Result<(), Box<dyn std::error::Error>> {
    debug!(
        "sync: enter (bookmark={}, remote={})",
        params.bookmark, params.remote
    );

    // Preflight: verify bookmark tracking on every repo before any
    // fetch/rebase. Implements "Non-tracking-remote bookmark detection",
    // design at:
    //   https://github.com/winksaville/vc-x1/blob/main/notes/chores/chores-06.md#non-tracking-remote-bookmark-detection-design
    for repo in repos {
        let bookmark = repo_bookmark(repo, &params.bookmark);
        if bookmark != params.bookmark {
            info!(
                "{}: bot repo, syncing 'main' ('{}' is a work repo bookmark)",
                repo.display(),
                params.bookmark
            );
        }
        crate::common::verify_tracking(repo, bookmark)?;
    }

    // In-memory only: a watch exists to restore or be printed by this
    // invocation, never persisted for a later one.
    let mut watches: Vec<Watch> = Vec::new();
    for repo in repos {
        watches.push(Watch::open(ctx, repo)?);
    }

    // Run the plan, then reposition `@` onto the freshly-synced
    // bookmark. Both live inside the same all-or-nothing region.
    //
    // A look-only run and a repo restored for want of a go skip the
    // reposition: neither moved a bookmark, so `@` has nowhere new to
    // go.
    let result = run_plan(ctx, &mut watches, params).and_then(|left| {
        if !params.dry_run {
            for watch in watches.iter_mut() {
                if !left.contains(&watch.path) {
                    watch.look(ctx)?;
                    let bookmark = repo_bookmark(&watch.path, &params.bookmark);
                    reposition_at(&watch.path, bookmark, params)?;
                    watch.mine()?;
                }
            }
        }
        Ok(left)
    });

    let left = match result {
        Ok(left) => left,
        Err(e) if params.keep => {
            warn!("sync failed: {e}");
            warn!("stopping: state left as-is for inspection (--keep)");
            warn!("pre-sync op snapshot per repo:");
            for watch in &watches {
                warn!("  {}: op {}", watch.path.display(), watch.found_op);
            }
            warn!("undo per repo: jj op restore <op> -R <repo>");
            debug!("sync: exit");
            return Err(e);
        }
        Err(e) => {
            warn!("sync failed: {e}");
            for watch in watches.iter_mut() {
                watch.restore(ctx)?;
            }
            warn!("rerun with --keep to leave the failed state in place for inspection");
            debug!("sync: exit");
            return Err(e);
        }
    };

    debug!("sync: exit");
    // Not a failed step: every other repo synced, and these are as
    // found.
    if !left.is_empty() {
        let names: Vec<String> = left.iter().map(|r| r.display().to_string()).collect();
        return Err(format!(
            "diverged and left as found: {}: rerun with --rebase to rebase onto the remote",
            names.join(", ")
        )
        .into());
    }
    Ok(())
}

""")

