cut("/// Fetch and classify each repo, then act, or in a look-only run",
    "/// Fetch `repo` from `remote` without streaming chatter", """/// Fetch and classify each repo, then act, or in a look-only run
/// restore what the fetch changed.
///
/// Returns the repos restored for want of a go, empty when every
/// repo synced and always empty for a look-only run. Returns `Err`
/// on the first failure, a conflict the fetch left included, so the
/// caller can restore or keep (see `sync_repos`).
fn run_plan(
    ctx: &mut Context,
    watches: &mut [Watch],
    params: &SyncParams,
) -> Result<Vec<PathBuf>, Box<dyn std::error::Error>> {
    // Phase 1: fetch + classify silently.
    //
    // Each repo's fetch stderr is captured (rather than streamed to
    // `info!` via `common::run`) so we can decide after classification
    // whether to surface it. `jj git fetch`'s routine "Nothing
    // changed." chatter is the main thing we're suppressing here:
    // if nothing needs action, the user shouldn't see it.
    let mut fetched: Vec<(PathBuf, Vec<String>)> = Vec::new();
    let mut ctxs: Vec<RepoCtx> = Vec::new();
    //
    // The bookmark is read before the fetch: the fetch moves a
    // tracked bookmark that is behind and conflicts one that
    // diverged, so afterwards neither state can be told from the
    // bookmark alone.
    for watch in watches.iter_mut() {
        let repo = &watch.path;
        let bookmark = repo_bookmark(repo, &params.bookmark);
        let found = local_bookmark_heads(repo, bookmark)?;
        let had_conflicts = has_conflicts(repo)?;
        let lines = fetch_silent(ctx, repo, &params.remote)?;
        watch.mine()?;
        fetched.push((repo.clone(), lines));
        let state = classify(repo, &found, bookmark, &params.remote)?;
        let conflicted = !had_conflicts && has_conflicts(repo)?;
        ctxs.push(RepoCtx {
            path: repo.clone(),
            found,
            state,
            conflicted,
        });
    }

    // Ahead is not level either, and a reader of the report wants to
    // hear of an unpushed bookmark, so only up-to-date is quiet.
    let any_action_needed = ctxs
        .iter()
        .any(|c| c.conflicted || !matches!(c.state, State::UpToDate | State::NoRemote));

    // Phase 2: emit status. `--quiet` is enforced globally via the
    // log-level clamp in `sync()`, so these `info!` calls are already
    // suppressed in scripts. We just shape the output here.
    if !any_action_needed {
        let n = ctxs.len();
        let noun = if n == 1 { "repo is" } else { "repos are" };
        info!("sync: {n} {noun} {UP_TO_DATE_MSG}");
    } else {
        for (repo, lines) in &fetched {
            info!("{}: fetch {}", repo.display(), params.remote);
            for line in lines {
                info!("{line}");
            }
        }
        for ctx in &ctxs {
            log_state(&ctx.path, &ctx.state, params.dry_run);
            if ctx.conflicted && params.dry_run {
                info!(
                    "{}: the fetch conflicts with local work; a sync would fail and restore",
                    ctx.path.display()
                );
            }
        }
    }

    // Phase 3: act, or for a look restore. Repositioning `@` onto the
    // synced bookmark happens after `run_plan` returns (see
    // `sync_repos`), inside the same all-or-nothing region.
    let mut left = Vec::new();
    for (repo_ctx, watch) in ctxs.iter().zip(watches.iter_mut()) {
        if params.dry_run {
            if !watch.restore(ctx)? {
                return Err(format!("{}: could not be left as found", watch.path.display()).into());
            }
            continue;
        }
        if repo_ctx.conflicted {
            return Err(format!(
                "{}: the fetch conflicts with local work (the remote rewrote a commit under it)",
                repo_ctx.path.display()
            )
            .into());
        }
        watch.look(ctx)?;
        let acted = act_on_state(ctx, repo_ctx, params)?;
        watch.mine()?;
        if acted == Acted::NoGo {
            if !watch.restore(ctx)? {
                return Err(format!("{}: could not be left as found", watch.path.display()).into());
            }
            left.push(repo_ctx.path.clone());
        }
    }

    Ok(left)
}

""")

# ---- act_on_state
cut("/// Perform the mutation corresponding to `repo_ctx.state` (a",
    "/// Print a single-line summary of `state`", """/// Perform the mutation corresponding to `repo_ctx.state` (a
/// look-only run never gets here, see `run_plan`).
///
/// - `UpToDate` / `Ahead` / `NoRemote` -> no-op (and no output, the state
///   was already logged by `log_state`).
/// - `Behind` -> `jj bookmark set <b> -r <b>@<remote>` to fast-forward.
///   The fetch has usually moved a tracked bookmark there already, and
///   the set is what covers the one it did not.
/// - `Rewritten` -> no-op: the fetch followed the rewrite, and a
///   conflict it left was failed on before this (see `run_plan`).
/// - `Diverged` -> only on a go, `--rebase` or a yes at the prompt:
///   `jj rebase -b <b> -d <b>@<remote>`, then probe `conflicts()`. A
///   non-empty result means the rebase produced conflicted commits,
///   and the `Err` fails the run. With no go, `NoGo`: the caller
///   restores the repo, lets the others sync, and fails the run after.
fn act_on_state(
    ctx: &mut Context,
    repo_ctx: &RepoCtx,
    params: &SyncParams,
) -> Result<Acted, Box<dyn std::error::Error>> {
    let repo = &repo_ctx.path;
    let bookmark = repo_bookmark(repo, &params.bookmark);
    let remote_rev = format!("{}@{}", bookmark, params.remote);
    match &repo_ctx.state {
        State::UpToDate | State::Ahead { .. } | State::NoRemote => Ok(Acted::Synced),
        State::Behind { .. } => {
            info!("{}: setting '{bookmark}' to {remote_rev}", repo.display());
            ctx.session(repo)?.bookmark_set(bookmark, &remote_rev)?;
            Ok(Acted::Synced)
        }
        State::Rewritten { .. } => {
            info!("{}: '{bookmark}' followed the rewrite", repo.display());
            Ok(Acted::Synced)
        }
        State::Diverged { local, remote } => {
            let question = format!("'{bookmark}' diverged: rebase it onto {remote_rev}?");
            if !params.rebase && !confirm_rebase(repo, &question)? {
                info!(
                    "{}: '{bookmark}' is left as found (pass --rebase to rebase onto {remote_rev})",
                    repo.display()
                );
                return Ok(Acted::NoGo);
            }
            // `local` is either a single commit id or a comma-joined list
            // of heads when the bookmark was conflicted before the fetch.
            // Pick the head that isn't the remote: that's the local-only
            // tip.
            let local_head = local
                .split(',')
                .find(|h| *h != remote)
                .unwrap_or(local.as_str());
            info!(
                "{}: rebasing {local_head} onto {remote_rev}",
                repo.display()
            );
            ctx.session(repo)?.rebase_branch(local_head, &remote_rev)?;
            if has_conflicts(repo)? {
                return Err(format!("{}: rebase produced conflicts", repo.display()).into());
            }
            Ok(Acted::Synced)
        }
    }
}

